ST.xhtml:p:
Rtring_trigger(CLK := WaitCheckEnable);
IF Rtring_trigger.Q THEN
  Ton_time(IN := FALSE);
  Ton_time1(IN := FALSE);
  nWaitState := 10;
  OutPut := 1; 
   WaitCheckEnable := FALSE; 
END_IF;
Rtring_trigger1(CLK := ChangeOutput);
IF Rtring_trigger1.Q THEN

  OutPut := 1; 

END_IF;

CASE nWaitState OF
  0:
	nWaitState := 0;
  10:
    Ton_time(IN := TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(LREAL_TO_DINT(WaitInputPortAlarmTime))));
    IF WaitInputPortBoardType = 0.0 THEN
				IF WaitInputPortJudgeType = 0.0 THEN  
					IF BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)-1] THEN
						Ton_time(IN := FALSE);
                        IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
				ELSE
					IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)-1]  THEN
						Ton_time(IN := FALSE);
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
                END_IF;
	ELSIF WaitInputPortBoardType = 1.0 THEN
				IF WaitInputPortJudgeType = 0.0 THEN
					IF BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+23] THEN
						Ton_time(IN := FALSE);
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
				ELSE
					IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+23] THEN
						Ton_time(IN := FALSE);
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
				END_IF;
	ELSIF WaitInputPortBoardType = 2.0 THEN
				IF WaitInputPortJudgeType = 0.0 THEN
					IF  BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+47] THEN
						Ton_time(IN := FALSE);
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
				ELSE
					IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+47]  THEN
						Ton_time(IN := FALSE);
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
				END_IF;
	ELSIF WaitInputPortBoardType = 3.0 THEN
				IF WaitInputPortJudgeType = 0.0 THEN
					IF  BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+71] THEN
						Ton_time(IN := FALSE);
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
				ELSE
					IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+71]  THEN
						Ton_time(IN := FALSE);
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
					END_IF;
				END_IF;
	END_IF;   
	IF Ton_time.Q THEN
				Ton_time(IN := FALSE);
				IF WaitInputPortExecuteType = 1.0 THEN
					g_bWaitInputPorTimeOutContinueAlarm := TRUE;
						IF WaitCheckMode = 1 THEN
							nWaitState := 11;
                        ELSE
							OutPut := 0;
							nWaitState := 0;
                        END_IF;
				ELSE
					IF WaitInputPortBoardType = 0.0 THEN
						IF WaitInputPortJudgeType = 0.0 THEN
							IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)-1] THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						ELSE
							IF  BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)-1]  THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						END_IF;
					ELSIF WaitInputPortBoardType = 1.0 THEN
						IF WaitInputPortJudgeType = 0.0 THEN
							IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+23] THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						ELSE
							IF  BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+23] THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						END_IF;
					ELSIF WaitInputPortBoardType = 2.0 THEN
						IF WaitInputPortJudgeType = 0.0 THEN
							IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+47] THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						ELSE
							IF BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+47]  THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						END_IF;
					ELSIF WaitInputPortBoardType = 3.0 THEN
						IF WaitInputPortJudgeType = 0.0 THEN
							IF NOT BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+71] THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						ELSE
							IF BoardInPutArray.BoolArr[LREAL_TO_INT(WaitInputPortNumber)+71]  THEN
								g_bWaitInputPorTimeOutAlarm := TRUE;
								nWaitState := 0;
							END_IF;
						END_IF;
					END_IF;
				END_IF;
                (*传报警值给到界面 nWaitInputPorTimeOutAlarmNumber1-24表示第一张板卡DI1-DI24; 25-48表示第二张板卡DI1-DI24;  49-72表示第三张板卡DI1-DI24*)
				IF WaitInputPortBoardType = 0.0  THEN
				  g_dWaitInputPorTimeOutAlarmNumber := WaitInputPortNumber;
				ELSIF WaitInputPortBoardType = 1.0 THEN
				  g_dWaitInputPorTimeOutAlarmNumber := WaitInputPortNumber+24.0;
				ELSIF WaitInputPortBoardType = 2.0 THEN
				  g_dWaitInputPorTimeOutAlarmNumber := WaitInputPortNumber+48.0; 
				ELSIF WaitInputPortBoardType = 3.0 THEN
				  g_dWaitInputPorTimeOutAlarmNumber := WaitInputPortNumber+72.0;   
				END_IF; 
				nWaitState := 0;
			END_IF;
    11:
		Ton_time1(IN := TRUE,PT := T#100ms);
		IF Ton_time1.Q THEN
			OutPut := 0;
			nWaitState := 0;
            Ton_time1(IN := FALSE);
        END_IF;
END_CASE;




IF g_bPlcResetBuffer THEN

  WaitCheckEnable := FALSE;
  IF WaitCheckMode = 1 THEN
  (*如果开启了并行实时刷新的就不要关了,可能在实时刷新*)
        IF g_bRealTimeUpdateParallePLC AND g_bRealTimeUpdateParallePLCExecuteFlag THEN
			IF g_nRealTimeUpdateParallePLCIndex <> UpdateIndex THEN
				OutPut := 1; 
                nWaitState := 0;
            END_IF;
		ELSE
			 OutPut := 1; 
             nWaitState := 0;
		END_IF;	
  ELSE
    nWaitState := 0;
    OutPut := 0;
  END_IF;
END_IF;
